//! Exact plain Möbius renderer for autonomous one-base FSC terminals.
//!
//! The embedded certificate is a typed, reproducible table generated by the
//! exhaustive ignored test at the bottom of this module.

use crate::{
    expr::Expr,
    factorized_section::{OneBaseDescriptor, compile_declared_one_base_descriptor},
};

// Generated offline with:
//
// cargo test -p rumba-core --release --features parse \
//   certificate_matches_exhaustive_generator -- --ignored --nocapture
//
// The generator below exhaustively enumerates every canonical production
// expression of AST cost <= 3 over constants 0..63, x/y, NOT, Scale, AND, OR,
// XOR, Add, and Mul. It evaluates the full 64x64 input table modulo 64, retains
// exactly the functions representable by (c0,c1,c2,c12), and records their
// minimum cost. Enumerating costs below four proves whether a candidate of cost
// <= 4 has a cheaper equivalent; enumeration never runs in production.
//
// Entries are sorted packed u32 values. The tuple key is
// c0 | (c1 << 6) | (c2 << 12) | (c12 << 18), and an entry is encoded as
// (key << 2) | minimum_cost. The expected output is 568 entries.
