fn scaled(coefficient: i128, expression: Expr) -> Expr {
    Expr::scale(coefficient as u64, expression)
}

pub(crate) fn render_plain(descriptor: OneBaseDescriptor) -> Option<Expr> {
    let [c1, c2, xy_value] = descriptor.epsilon_nonzero;
    let c12 = xy_value.checked_sub(c1)?.checked_sub(c2)?;
    let [x, y] = descriptor.variables.map(Expr::Var);
    let mut terms = Vec::with_capacity(4);
    if descriptor.r0 != 0 {
        terms.push(Expr::Const(descriptor.r0 as u64));
    }
    if c1 != 0 {
        terms.push(scaled(c1, x.clone()));
    }
    if c2 != 0 {
        terms.push(scaled(c2, y.clone()));
    }
    if c12 != 0 {
        terms.push(scaled(c12, Expr::And(vec![x, y])));
    }
    Some(match terms.len() {
        0 => Expr::Const(0),
        1 => terms.pop()?,
        _ => Expr::Add(terms),
    })
}

fn same_descriptor(left: OneBaseDescriptor, right: OneBaseDescriptor) -> bool {
    left.variables == right.variables
        && left.r0 == right.r0
        && left.epsilon_nonzero == right.epsilon_nonzero
}

fn tuple_key(descriptor: OneBaseDescriptor) -> Option<u32> {
    let [c1, c2, xy_value] = descriptor.epsilon_nonzero;
    let coefficients = [
        descriptor.r0,
        c1,
        c2,
        xy_value.checked_sub(c1)?.checked_sub(c2)?,
    ];
    Some(
        coefficients
            .into_iter()
            .enumerate()
            .fold(0u32, |key, (index, value)| {
                key | (((value as u64 & 63) as u32) << (index * 6))
            }),
    )
}

fn minimum_cost(key: u32) -> Option<u8> {
    let index = CERTIFICATE_TABLE
        .binary_search_by_key(&key, |packed| packed >> 2)
        .ok()?;
    Some((CERTIFICATE_TABLE[index] & 3) as u8)
}

fn minimality_certified(descriptor: OneBaseDescriptor, cost: usize) -> bool {
    if !(1..=4).contains(&cost) {
        return false;
    }
    tuple_key(descriptor)
        .and_then(minimum_cost)
        .is_none_or(|minimum| usize::from(minimum) >= cost)
}

pub(crate) fn render_terminal(descriptor: OneBaseDescriptor) -> Option<Expr> {
    let candidate = render_plain(descriptor)?;
    let compiled = compile_declared_one_base_descriptor(&candidate, descriptor.variables)?;
    (same_descriptor(compiled, descriptor) && minimality_certified(descriptor, candidate.size()))
        .then_some(candidate)
}

#[cfg(test)]
mod tests {
    use std::collections::{BTreeMap, BTreeSet};

    use super::*;
    use crate::expr::VarId;
    #[cfg(feature = "parse")]
    use crate::parser::parse_expr;

    const VARIABLES: [VarId; 2] = [VarId(0), VarId(1)];

    #[cfg(feature = "parse")]
    fn descriptor(source: &str) -> OneBaseDescriptor {
        compile_declared_one_base_descriptor(
            &parse_expr(source).expect("test expression"),
            VARIABLES,
        )
        .expect("one-base descriptor")
    }

    #[test]
    #[cfg(feature = "parse")]
    fn plain_candidates_recompile_exactly() {
        for source in [
            "7 + 3*v0 - 5*v1",
            "9 + 4*v0 + 6*v1 + 8*(v0&v1)",
            "9223372036854775807*v0 - 9*v1",
        ] {
            let source = descriptor(source);
            let candidate = render_plain(source).expect("plain candidate");
            let compiled = compile_declared_one_base_descriptor(&candidate, VARIABLES)
                .expect("candidate descriptor");
            assert!(same_descriptor(compiled, source));
        }
    }

    #[test]
    #[cfg(feature = "parse")]
    fn minimality_gate_accepts_cost_four_and_rejects_cost_five() {
        let descriptor = descriptor("1 + 2*v0");
        let candidate = render_terminal(descriptor).expect("cost-four terminal");
        assert_eq!(candidate.size(), 4);
        assert!(!minimality_certified(descriptor, 5));
    }

    #[test]
    fn certificate_is_well_formed() {
        assert_eq!(CERTIFICATE_TABLE.len(), 568);
        assert!(
            CERTIFICATE_TABLE
                .iter()
                .all(|packed| matches!(packed & 3, 1..=3))
        );
        assert!(
            CERTIFICATE_TABLE
                .windows(2)
                .all(|pair| pair[0] >> 2 < pair[1] >> 2)
        );
    }

    fn insert_cost(expression: Expr, costs: &mut [BTreeSet<Expr>; 4]) {
        let expression = match expression {
            Expr::Const(value) => Expr::Const(value & 63),
            expression => expression,
        };
        let cost = expression.size();
        if cost <= 3 {
            costs[cost].insert(expression);
        }
    }

    fn eval_mod64(expression: &Expr, variables: [u8; 2]) -> u8 {
        match expression {
            Expr::Var(variable) => variables[variable.0] & 63,
            Expr::Const(value) => (value & 63) as u8,
            Expr::Not(child) => !eval_mod64(child, variables) & 63,
            Expr::Scale(coefficient, child) => {
                ((coefficient & 63) as u8).wrapping_mul(eval_mod64(child, variables)) & 63
            }
            Expr::And(children) => children
                .iter()
                .map(|child| eval_mod64(child, variables))
                .fold(63, |left, right| left & right),
            Expr::Or(children) => children
                .iter()
                .map(|child| eval_mod64(child, variables))
                .fold(0, |left, right| left | right),
            Expr::Xor(children) => children
                .iter()
                .map(|child| eval_mod64(child, variables))
                .fold(0, |left, right| left ^ right),
            Expr::Add(children) => {
                children
                    .iter()
                    .map(|child| eval_mod64(child, variables))
                    .fold(0u8, u8::wrapping_add)
                    & 63
            }
            Expr::Mul(children) => {
                children
                    .iter()
                    .map(|child| eval_mod64(child, variables))
                    .fold(1u8, u8::wrapping_mul)
                    & 63
            }
        }
    }

    fn reduced_onebase_key(expression: &Expr) -> Option<u32> {
        let c0 = eval_mod64(expression, [0, 0]);
        let c1 = eval_mod64(expression, [1, 0]).wrapping_sub(c0) & 63;
        let c2 = eval_mod64(expression, [0, 1]).wrapping_sub(c0) & 63;
        let c12 = eval_mod64(expression, [1, 1])
            .wrapping_sub(c0)
            .wrapping_sub(c1)
            .wrapping_sub(c2)
            & 63;
        for x in 0..64u8 {
            for y in 0..64u8 {
                let expected = c0
                    .wrapping_add(c1.wrapping_mul(x))
                    .wrapping_add(c2.wrapping_mul(y))
                    .wrapping_add(c12.wrapping_mul(x & y))
                    & 63;
                if eval_mod64(expression, [x, y]) != expected {
                    return None;
                }
            }
        }
        Some(u32::from(c0) | (u32::from(c1) << 6) | (u32::from(c2) << 12) | (u32::from(c12) << 18))
    }

    fn generated_certificate() -> Vec<u32> {
        // Exhaustive production grammar at AST cost < 4:
        // constants, x/y, NOT, Scale, AND, OR, XOR, Add, and Mul.
        let mut costs: [BTreeSet<Expr>; 4] = std::array::from_fn(|_| BTreeSet::new());
        for constant in 0..64u64 {
            insert_cost(Expr::Const(constant), &mut costs);
        }
        insert_cost(Expr::Var(VARIABLES[0]), &mut costs);
        insert_cost(Expr::Var(VARIABLES[1]), &mut costs);

        let leaves = costs[1].iter().cloned().collect::<Vec<_>>();
        for child in &leaves {
            insert_cost(Expr::Not(Box::new(child.clone())), &mut costs);
            for coefficient in 0..64u64 {
                insert_cost(Expr::scale(coefficient, child.clone()), &mut costs);
            }
        }
        let unary_children = costs[2].iter().cloned().collect::<Vec<_>>();
        for child in &unary_children {
            insert_cost(Expr::Not(Box::new(child.clone())), &mut costs);
            for coefficient in 0..64u64 {
                insert_cost(Expr::scale(coefficient, child.clone()), &mut costs);
            }
        }
        for (left_index, left) in leaves.iter().enumerate() {
            for right in leaves.iter().skip(left_index) {
                for expression in [
                    Expr::And(vec![left.clone(), right.clone()]),
                    Expr::Or(vec![left.clone(), right.clone()]),
                    Expr::Xor(vec![left.clone(), right.clone()]),
                    Expr::Add(vec![left.clone(), right.clone()]),
                    Expr::product(vec![left.clone(), right.clone()]),
                ] {
                    insert_cost(expression, &mut costs);
                }
            }
        }

        let mut minimum = BTreeMap::<u32, u8>::new();
        for (cost, expressions) in costs.iter().enumerate().skip(1) {
            for expression in expressions {
                let Some(key) = reduced_onebase_key(expression) else {
                    continue;
                };
                minimum
                    .entry(key)
                    .and_modify(|current| *current = (*current).min(cost as u8))
                    .or_insert(cost as u8);
            }
        }
        minimum
            .into_iter()
            .map(|(key, cost)| (key << 2) | u32::from(cost))
            .collect()
    }

    #[test]
    #[ignore = "exhaustively regenerates the modulo-64 AST<4 certificate"]
    fn certificate_matches_exhaustive_generator() {
        let certificate = generated_certificate();
        assert_eq!(certificate.as_slice(), CERTIFICATE_TABLE.as_slice());
        assert_eq!(certificate.len(), 568);
    }
}
